const num = 4; 

function setup() {
  createCanvas(400, 400);
}

function draw() {
  background("azure");
  noFill()
  translate(0, width * 0.5);

  drawGrid();
  drawSine();
}

function drawGrid() {
  stroke(212, 32, 32)
  strokeWeight(1)
  line(0, 0, width, 0)
  stroke(212, 32, 32, 64)
  for (let x = 0; x < width; x+= width / num) {
    line(x, -height * 0.5, x, height * 0.5)
  }
}

function drawSine() {
  let vals = [];

  let a = frameCount * 0.01;
  stroke("gray")
  strokeWeight(3)
  beginShape();
  let sum = 0;
  let part = [];
  for (let x = 0; x < width; x++) {
    const y = sin(a + map(x, 0, width, 0, TWO_PI));
    vertex(x, y * height * 0.5)
    if (x % floor(width / num) === 0) {
      push();
      line(x, y * height * 0.5, x + width / num, y * height * 0.5)
      noStroke()
      fill(0)
      const v = (y + 1) / 2
      part.push(v);
      sum += v;
      textAlign(LEFT)
      if (x === width) textAlign(RIGHT)
      text("" + nf(v, 1, 2) + " / " + nf(sum, 1, 2), x, y * height * 0.5)
      pop();
    }
  }
  endShape();

  push()
  resetMatrix();
  // translate(0, -height * 0.5)
  const clrs = [color(128, 32, 64, 64), color(32, 128, 64, 64)]
  noStroke(); 
  for (let i = 0, x = 0; i < part.length; i++) {
    const w = part[i]/sum * width;
    fill(clrs[i % clrs.length])
    rect(x, 0, w, height)
    fill(32)
    text("" + nf(w, 1, 1), x, 10)
    x += w;
  }
  if (false && frameCount % 100 === 0) {
    console.log("sum = " + sum)
    console.table(part);
  }
  pop();
}
